#!/usr/bin/env bash
set -euo pipefail
umask 077

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
env_file="${ENV_FILE:-/private/tmp/scientificresearch-uat-tokens.env}"
[[ -f "$env_file" ]] || {
  echo "UAT 令牌文件不存在: $env_file" >&2
  exit 1
}
[[ "$(stat -f '%Lp' "$env_file" 2>/dev/null || stat -c '%a' "$env_file")" == "600" ]] || {
  echo "UAT 令牌文件权限必须为 600: $env_file" >&2
  exit 1
}

# The file is generated by prepare-scientificresearch-uat-tokens-watch.sh.
# Never echo its contents or include tokens in reports.
set -a
# shellcheck disable=SC1090
. "$env_file"
set +a

required=(RESEARCHER_TOKEN DEPARTMENT_LEAD_TOKEN SECRETARY_TOKEN EXPERT_TOKEN FINANCE_TOKEN SYSTEM_ADMIN_TOKEN)
for name in "${required[@]}"; do
  value="${!name:-}"
  [[ "$value" == eyJ*.*.* ]] || {
    echo "UAT 令牌缺失或格式无效: $name（令牌内容不显示）" >&2
    exit 1
  }
done

export AUTH_BOUNDARIES_ROLE_TESTS=true
export AUTH_BOUNDARIES_NON_ADMIN_TOKEN="$RESEARCHER_TOKEN"
export AUTH_BOUNDARIES_ADMIN_TOKEN="$SYSTEM_ADMIN_TOKEN"
export AUTH_BOUNDARIES_SIX_ROLE_TESTS=true
export AUTH_BOUNDARIES_RESEARCHER_TOKEN="$RESEARCHER_TOKEN"
export AUTH_BOUNDARIES_DEPARTMENT_LEAD_TOKEN="$DEPARTMENT_LEAD_TOKEN"
export AUTH_BOUNDARIES_SECRETARY_TOKEN="$SECRETARY_TOKEN"
export AUTH_BOUNDARIES_EXPERT_TOKEN="$EXPERT_TOKEN"
export AUTH_BOUNDARIES_FINANCE_TOKEN="$FINANCE_TOKEN"
export AUTH_BOUNDARIES_SYSTEM_ADMIN_TOKEN="$SYSTEM_ADMIN_TOKEN"
export ETHICS_P2_TOKEN="$SYSTEM_ADMIN_TOKEN"

echo '开始六角色权限边界验收（令牌内容不显示）'
APP_BASE_URL="${APP_BASE_URL:-http://127.0.0.1:16379}" \
  KEYCLOAK_BASE_URL="${KEYCLOAK_BASE_URL:-http://127.0.0.1:8180}" \
  "$root/deploy/verify-auth-boundaries.sh"

echo '开始伦理 P2 只读验收（不写入业务数据）'
APP_BASE_URL="${APP_BASE_URL:-http://127.0.0.1:16379}" \
  "$root/deploy/verify-ethics-p2-acceptance.sh"

echo '六角色权限与伦理 P2 只读验收完成'
